using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Text;using System.Threading.Tasks;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Interop;using System.Web.Script.Serialization;using Microsoft.VisualStudio.Shell;using Microsoft.VisualStudio.ComponentModelHost;using Microsoft.VisualStudio.Editor;using Microsoft.VisualStudio.TextManager.Interop;
namespace CodeAssist.ParityRunner {
internal static class BackgroundCapture {
[DllImport("user32.dll")]static extern IntPtr GetThreadDesktop(uint tid);[DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();[DllImport("user32.dll")]static extern IntPtr OpenInputDesktop(uint f,bool i,uint access);[DllImport("user32.dll")]static extern bool CloseDesktop(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetUserObjectInformation(IntPtr h,int n,StringBuilder s,int size,out int need);
static Microsoft.VisualStudio.Threading.JoinableTask activeInput;
static string Name(IntPtr h){int n;var s=new StringBuilder(512);if(!GetUserObjectInformation(h,2,s,1024,out n))throw new InvalidOperationException("Cannot read desktop");return s.ToString();}
static void Guard(){var own=Name(GetThreadDesktop(GetCurrentThreadId()));var input=OpenInputDesktop(0,false,1);try{if((!own.StartsWith("CodeAssistVerify-")||Name(input)==own)&&!(own=="Default"&&Environment.GetEnvironmentVariable("CODEASSIST_FOREGROUND_VALIDATION")=="1"))throw new InvalidOperationException("Refusing input desktop capture service without explicit foreground validation opt-in");}finally{CloseDesktop(input);}}
internal static async Task Serve(AsyncPackage package,string root,string role) {
if(Environment.GetEnvironmentVariable("CODEASSIST_BACKGROUND_CAPTURE")!="1")return;
var json=new JavaScriptSerializer{MaxJsonLength=16000000};string request=Path.Combine(root,role+".capture-request.json"),seen=null;int heartbeat=0;var folder=Path.Combine(root,"background-capture");Directory.CreateDirectory(folder);
while(!package.DisposalToken.IsCancellationRequested){await Task.Delay(250);if(++heartbeat%20==0)File.WriteAllText(Path.Combine(root,role+".capture-heartbeat.txt"),DateTimeOffset.Now.ToString("o"));if(!File.Exists(request))continue;string payload=File.ReadAllText(request);if(payload==seen)continue;seen=payload;string id="invalid";
try{var item=json.Deserialize<Dictionary<string,object>>(payload);id=(string)item["id"];if(id.Length>80||!System.Text.RegularExpressions.Regex.IsMatch(id,"^[A-Za-z0-9_-]+$"))throw new InvalidOperationException("Invalid capture id");await package.JoinableTaskFactory.SwitchToMainThreadAsync();Guard();if(File.Exists(Path.Combine(folder,role+"-"+id+".json"))||File.Exists(Path.Combine(folder,role+"-"+id+"-probe.json"))||File.Exists(Path.Combine(folder,role+"-"+id+"-module.json")))continue;if(item.ContainsKey("kind")){if((string)item["kind"]=="module"){await LiveModule.RunAsync(package,root,role,item,id);continue;}if(activeInput!=null&&!activeInput.Task.IsCompleted)throw new InvalidOperationException("Previous input request is still active");var capturedId=id;var capturedItem=item;activeInput=package.JoinableTaskFactory.RunAsync(async()=>{await Task.Yield();await InProcessEditorProbe.RunAsync(package,root,role,capturedItem,capturedId);});continue;}var dte=await package.GetServiceAsync(typeof(EnvDTE.DTE)) as EnvDTE80.DTE2;var rows=new List<object>();
Action<Visual,string> capture=(visual,label)=>{try{var element=visual as FrameworkElement;if(element==null)throw new InvalidOperationException("No framework visual");element.UpdateLayout();var size=element.RenderSize;var dpi=VisualTreeHelper.GetDpi(element);int width=(int)Math.Ceiling(size.Width*dpi.DpiScaleX),height=(int)Math.Ceiling(size.Height*dpi.DpiScaleY);if(width<10||height<10||width>10000||height>10000)throw new InvalidOperationException("Invalid visual dimensions "+size);var bitmap=new RenderTargetBitmap(width,height,96*dpi.DpiScaleX,96*dpi.DpiScaleY,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen()){dc.DrawRectangle(new VisualBrush(visual){Stretch=Stretch.None,AlignmentX=AlignmentX.Left,AlignmentY=AlignmentY.Top},null,new Rect(0,0,size.Width,size.Height));}bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));var path=Path.Combine(folder,role+"-"+id+"-"+label+".png");using(var file=File.Create(path))encoder.Save(file);rows.Add(new{label,status="captured",width,height,path,method="WPF RenderTargetBitmap",logicalWidth=size.Width,logicalHeight=size.Height});}catch(Exception ex){rows.Add(new{label,status="error",error=ex.ToString()});}};
var hwnd=(IntPtr)dte.MainWindow.HWnd;var source=HwndSource.FromHwnd(hwnd);if(source!=null)capture(source.RootVisual,"main");var manager=await package.GetServiceAsync(typeof(SVsTextManager)) as IVsTextManager;var model=await package.GetServiceAsync(typeof(SComponentModel)) as IComponentModel;IVsTextView adapter;if(manager!=null&&model!=null&&manager.GetActiveView(0,null,out adapter)>=0){var view=model.GetService<IVsEditorAdaptersFactoryService>().GetWpfTextView(adapter);if(view!=null)capture(view.VisualElement,"editor");}
foreach(Window window in Application.Current.Windows){if(window.IsVisible&&new WindowInteropHelper(window).Handle!=hwnd)capture(window,"dialog-"+rows.Count);}
File.WriteAllText(Path.Combine(folder,role+"-"+id+".json"),json.Serialize(new{id,role,pid=System.Diagnostics.Process.GetCurrentProcess().Id,activeFile=dte.ActiveDocument==null?null:dte.ActiveDocument.FullName,rows,at=DateTimeOffset.Now.ToString("o")}));}
catch(Exception ex){File.WriteAllText(Path.Combine(folder,role+"-"+id+".error.json"),ex.ToString());}}
}
}
}
